import json
D=['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
def J(x):
    if isinstance(x,str):
        try:
            return json.loads(x)
        except Exception:
            return None
    return x
def W(s):
    return ' '.join(D[int(x)] for x in s if x.isdigit())
def LO(s):
    return str(s).replace('İ','i').replace('I','ı').lower()
FILL=set(['kart','kartım','kartımı','kartımın','kartın','kartı','kartının','benim','bana','bu','şu','olan','isimli','adlı','borcunu','borcu','öğrenmek','istiyorum','istiyorum.','söyle'])
NEG=set(['değil','degil','hayır','olmayan','istemiyorum'])
def TK(s):
    r=LO(s)
    for ch in (chr(39),'’',',','.','?','!'):
        r=r.replace(ch,' ')
    return [x for x in r.split() if x]
def hit(nt,qs):
    return any(q==nt or (q.startswith(nt) and len(q)-len(nt)<=4) for q in qs)
def full(c,q):
    a=TK(c['name'])
    b=TK(q)
    return bool(a) and bool(b) and not any(x in NEG for x in b) and all(hit(nt,b) for nt in a)
def part(c,q):
    a=TK(c['name'])
    b=[x for x in TK(q) if x not in FILL]
    return bool(a) and bool(b) and not any(x in NEG for x in b) and all(hit(x,a) or any(nt.startswith(x) for nt in a) for x in b)
def fn(c,q):
    return full(c,q) or part(c,q)
def find(pl,q):
    m=[c for c in pl if fn(c,q)]
    if len(m)>1:
        f=[c for c in m if full(c,q)]
        if f:
            mx=max(len(TK(c['name'])) for c in f)
            m=[c for c in f if len(TK(c['name']))==mx]
    return m
def fits(c,d):
    n=c['n']
    k=len(d)
    if k==4:
        t=n[-4:]
    elif k==6:
        t=n[-6:]
    elif k>=12 and k==len(n):
        t=n
    else:
        return False
    return all(a=='*' or a==b for a,b in zip(t,d))
def nm(c):
    return c['name'] if c['name'] else 'sonu '+W(c['l4'])+' ile biten kart'
def pick(c):
    vars['sel_number']=c['n']
    vars['sel_last4']=c['l4']
    vars['sel_l4w']=W(c['l4'])
    vars['sel_name']=c['name']
try:
    pool=J(vars.get('sel_pool')) or []
    allc=J(vars.get('elig_json')) or []
    ine=J(vars.get('inelig_json')) or []
    kind=str(vars.get('sel_kind') or '')
    q=str(vars.get('card_query') or '')
    d=''.join(x for x in str(vars.get('digits_said') or '') if x.isdigit())
    stage=str(vars.get('sel_stage') or 'name')
    sq=str(vars.get('stage_q') or 'Hangi kartınızın borcunu öğrenmek istersiniz?')
    t=int(vars.get('sel_tries') or 0)
    res='again'
    msg=''
    names=[]
    for c in allc:
        if nm(c) not in names:
            names.append(nm(c))
    allnames=', '.join(names)
    if kind=='all_cards':
        msg='Aynı anda yalnızca bir kartınızın borcunu okuyabiliyorum. '
        t+=1
    elif d:
        m=[c for c in pool if fits(c,d)]
        if len(m)==1:
            pick(m[0])
            res='done'
        elif not m:
            msg='Bu bilgiyle eşleşen bir kartınız bulunmuyor. '+('Kartlarınız: '+allnames+'. ' if stage=='name' else '')
            t+=1
        else:
            pool=m
            if len(d)==4:
                stage='last6'
                sq='Son dört hanesi '+W(d)+' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
            elif len(d)==6:
                stage='full'
                sq='Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
            else:
                msg='Bu bilgiyle kartı ayırt edemedim. '
                t+=1
    elif q and stage=='name':
        m=find(pool,q)
        if len(m)==1:
            pick(m[0])
            res='done'
        elif m:
            pool=m
            if len(set(c['name'] for c in m))==1:
                stage='last4'
                sq=m[0]['name']+' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?'
            else:
                sq='Bu isimle eşleşen kartlarınız: '+', '.join(nm(c) for c in m)+'. Hangisini istersiniz?'
        elif find(ine,q):
            msg='Bu kart için uygun bir kartınız bulunmuyor. Farklı bir kart söyler misiniz? '
            t+=1
        else:
            msg='Bu isimde bir kartınız bulunmuyor. Kartlarınız: '+allnames+'. '
            t+=1
    else:
        t+=1
        if kind=='unavailable':
            stage='name'
            pool=allc
            sq='Kartınızın adını söyler misiniz?'
    if res!='done' and t>=3:
        res='fail'
    vars['sel_pool']=json.dumps(pool,ensure_ascii=False)
    vars['sel_stage']=stage
    vars['stage_q']=sq
    vars['sel_prompt']=msg+sq
    vars['sel_tries']=str(t)
    vars['sel_state']=res
except Exception:
    vars['sel_state']='fail'
vars['sel_kind']=''
vars['card_query']=''
vars['digits_said']=''

try:
    for k,v in (('week_want',''),('week_pick','0'),('week_cancel',''),('week_confirm',''),('wk_tries','0'),('nm_choice','')):
        vars[k]=v
except Exception:
    pass

try:
    n=int(vars.get('sends_count') or 0)
    if n>=3:
        vars['email_go']='limit'
    elif vars.get('has_email')=='yes':
        vars['email_go']='confirm'
    else:
        vars['email_go']='none'
    for k in ('email_choice','limit_choice','nm_choice'):
        vars[k]=''
except Exception:
    vars['email_go']='none'

