import json
U=['','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
T=['','on','yirmi','otuz','kırk','elli','altmış','yetmiş','seksen','doksan']
M=['','Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
MS=['','tır','tır','tır','dır','tır','dır','dur','tur','dür','dir','dır','tır']
YS=['dır','dir','dir','tür','tür','tir','dır','dir','dir','dur']
CUR=dict(TL=('Türk Lirası','lira','kuruş'),USD=('Dolar','dolar','sent'),EUR=('Euro','euro','sent'),GBP=('İngiliz Sterlini','İngiliz Sterlini','peni'))
SF=dict(Lirası='dır',kuruş='tur',Dolar='dır',dolar='dır',Euro='dur',euro='dur',Sterlini='dir',sent='tir',peni='dir')
APO=chr(39)
def J(x):
    if isinstance(x,str):
        try:
            return json.loads(x)
        except Exception:
            return None
    return x
def tri(n):
    s=''
    h=n//100
    if h:
        s=('' if h==1 else U[h]+' ')+'yüz '
    s+=T[n//10%10]+' '+U[n%10]
    return ' '.join(s.split())
def W(n):
    if n==0:
        return 'sıfır'
    o=[]
    for v,nm in ((10**9,'milyar'),(10**6,'milyon'),(1000,'bin'),(1,'')):
        q=n//v
        n=n%v
        if q:
            o.append('bin' if nm=='bin' and q==1 else (tri(q)+' '+nm).strip())
    return ' '.join(o)
def A(x,c):
    p=int(round(abs(float(x))*100))
    k=p%100
    n=CUR[c]
    if k==0:
        return W(p//100)+' '+n[0]
    return W(p//100)+' '+n[1]+' '+W(k)+' '+n[2]
def E(x,c):
    a=A(x,c)
    return a+APO+SF.get(a.split()[-1],'dır')
def DT(s):
    p=str(s).split('.')
    return str(int(p[0]))+' '+M[int(p[1])]+' '+p[2]
def DN(s,y):
    return DT(s)
def DU(s,y):
    p=str(s).split('.')
    return str(int(p[0]))+' '+M[int(p[1])]+' '+p[2]+APO+YS[int(p[2][-1])]
def K(s):
    p=str(s).split('.')
    return (int(p[2]),int(p[1]),int(p[0]))
def F(x):
    try:
        return float(x)
    except Exception:
        return None
def G(b,k):
    o=J(vars.get('bal_'+b))
    if isinstance(o,dict) and o.get(k) is not None:
        return o.get(k)
    return vars.get('fetch_balance_response.data.data.debt'+b+'.'+k)
try:
    sc=str(vars.get('bal_http') or vars.get('fetch_balance_response.status_code') or '')
    if not (sc=='200' and str(vars.get('bal_rc') or '')=='1'):
        raise ValueError('bad')
    nw=str(vars.get('now'))[:10].split('-')
    today=nw[2]+'.'+nw[1]+'.'+nw[0]
    st=str(vars.get('bal_stmt') or '').strip()
    pay=str(vars.get('bal_pay') or '').strip()
    nx=str(vars.get('bal_next') or '').strip()
    cut=(nx==today)
    l4=str(vars.get('sel_l4w'))
    nme=str(vars.get('sel_name') or '')
    pre=(nme+' ') if nme else ''
    intro='Sonu '+l4+' ile biten '+pre+'kartınıza ait'
    B=dict()
    for c in ('TL','USD','EUR','GBP'):
        r=F(G(c,'remainingDebt'))
        td=F(G(c,'totalDebt'))
        basis=td if cut else r
        B[c]=((r is not None) or (td is not None), basis is not None and basis>0)
    fdue=''
    fmin=''
    if not st and not pay:
        txt='Sonu '+l4+' ile biten '+pre+'kartınız için. Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'
        if nx:
            txt+=' İlk hesap kesim tarihiniz '+DT(nx)+' olacak.'
        mode='nodebt'
    elif not any(v[1] for v in B.values()):
        txt='Sonu '+l4+' ile biten '+pre+'kartınızın '+((DT(st)+' tarihli ') if st else '')+'ekstresinden borcunuz bulunmamaktadır.'
        tt=F(G('TL','totalDebt'))
        if tt is not None and tt>0:
            txt+=' Gelecek dönemler dahil toplam borcunuz '+E(tt,'TL')+'.'
        if pay:
            txt+=' Son ödeme tarihiniz '+DN(pay,nw[0])+' olacaktır.'
        mode='nodebt'
    else:
        mode='debt'
        txt='Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. ' if cut else ''
        lead=intro+' '+((DT(st)+' tarihinde kesilen ekstre ') if (st and not cut) else '')
        nod=[]
        first=True
        for c in ('TL','USD','EUR','GBP'):
            ex,hd=B[c]
            if not ex:
                continue
            if not hd:
                nod.append(CUR[c][0])
                continue
            sd=G(c,'statementDebt')
            mp=G(c,'minPayment')
            rd=G(c,'remainingDebt')
            td=G(c,'totalDebt')
            rm=F(G(c,'remainingMinPayment'))
            mpf=F(mp)
            nmc=CUR[c][0]
            if cut:
                s=nmc+' borcunuz '+E(td,c)+'.'
            elif c=='TL':
                if rm is None or (rm>0 and mpf is not None and rm>=mpf):
                    s='Türk Lirası borcunuz '+A(sd,c)+', ödenmesi gereken minimum tutar '+E(mp,c)+'.'
                elif rm<=0:
                    s='Türk Lirası borcunuz '+A(sd,c)+', kalan toplam borcunuz '+E(rd,c)+'. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                else:
                    s='Türk Lirası borcunuz '+A(sd,c)+', ödenmesi gereken minimum tutar '+A(mp,c)+', kalan toplam borcunuz '+A(rd,c)+', kalan minimum ödeme tutarınız '+E(rm,c)+'.'
            else:
                s=nmc+' borcunuz '+A(sd,c)+', kalan toplam borcunuz '+A(rd,c)+', ödenmesi gereken minimum tutar '+E(mp,c)+'.'
            if c=='TL' and not cut:
                fmin='Ödenmesi gereken minimum tutar '+E(mp,c)+'.'
            txt+=(lead if first else '')+s+' '
            first=False
        if nod:
            txt+=(nod[0] if len(nod)==1 else ', '.join(nod[:-1])+' ve '+nod[-1])+' borcunuz bulunmamaktadır. '
        passed=bool(pay) and K(pay)<K(today)
        rem=F(G('TL','remainAutomaticPaymentAmount'))
        if passed and str(vars.get('bal_flag'))=='Y' and rem is not None and rem>0:
            txt+='Otomatik ödeme talimatınız kapsamında henüz tahsil edilecek '+A(rem,'TL')+' tutarı bulunmaktadır. '
        if pay:
            if K(pay)==K(today):
                fdue='Borçlarınız için son ödeme tarihiniz bugündür.'
            elif passed:
                tp=[A(F(G(c,'totalDebt')),c) for c in ('TL','USD','EUR','GBP') if B[c][0] and (F(G(c,'totalDebt')) or 0)>0]
                fdue='Borçlarınız için son ödeme tarihiniz geçmiş durumda.'+((' Toplam borcunuz '+', '.join(tp)+' tutarındadır.') if tp else '')
            else:
                fdue='Borçlarınız için son ödeme tarihiniz '+DU(pay,nw[0])+'.'
        txt+=fdue
    vars['reading_text']=txt.strip()
    vars['fact_due']=fdue
    vars['fact_min']=fmin
    vars['bal_mode']=mode
    if mode=='nodebt':
        vars['closing_q']='' if str(vars.get('elig_n'))=='1' else 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
        vars['offer_state']='none'
    vars['read_reply']=''
    vars['bal_state']='ok'
except Exception:
    vars['bal_state']='error'
vars['bal_http']=''
vars['bal_rc']=''

try:
    n=int(vars.get('silence_n') or 0)+1
    vars['silence_n']=str(n)
    if n>=3:
        vars['silence_say']='Sesinizi alamadığım için görüşmeyi sonlandırıyorum.'
except Exception:
    pass
